      "slurm": "#!/bin/bash\n\n### --------  SLURM  ----------- ###\n#SBATCH --job-name=continuous\n#SBATCH --nodes=1\n#SBATCH --ntasks=1\n#SBATCH --time=312:00:00\n#SBATCH --output=\"out/continuous_train_%A_%a_%j.out\"\n#SBATCH --error=\"error/continuous_train_%A_%a_%j.err\"\n### -------------------------- ###\necho \"job name: $SLURM_JOB_NAME\"\necho \"SLURM_JOBID:  $SLURM_JOBID\"\necho \"SLURM_ARRAY_TASK_ID: $SLURM_ARRAY_TASK_ID\"\necho \"SLURM_ARRAY_JOB_ID: $SLURM_ARRAY_JOB_ID\"\n\nexport LD_LIBRARY_PATH=/usr/local/cuda-9.0/lib64:/usr/local/lib\nexport CFLAGS=-I/usr/local/cuda-9.0/include\nexport LDFLAGS=-L/usr/local/cuda-9.0/lib64\nexport PATH=$PATH:/usr/local/cuda-9.0/bin\nexport CUDA_HOME=/usr/local/cuda-9.0\nexport LIBRARY_PATH=/usr/local/cuda-9.0/lib64\n\nsets=$1\npretrained=$2\nbl=$3\nemdim=$4\nname=$5\ntyppe=$6\nnlayer=$7\ntbrd=$8\npre_pos=$9\nloss=${10}\npre_more=${11}\nsrc=${12}\norig=${13}\n\nif [ \"$pre_pos\" == \"True\" ]\nthen\n  pos=--pos\nfi\n\nif [ \"$pre_more\" == \"True\" ] \nthen\n  more=--more\nfi\n\npython ${src}/continuous.py --data ${sets}/set_${SLURM_ARRAY_TASK_ID}/\\\n                            --pretrained ${pretrained}\\\n                            --save ${bl}_${SLURM_ARRAY_TASK_ID}.pt\\\n                            --emdim ${emdim}\\\n                            --log out/${name}_train_${SLURM_ARRAY_TASK_ID}\\\n                            --name $name\\\n                            --rnn_type ${typpe}\\\n                            --nlayers ${nlayer}\\\n                            --tbrd ${tbrd}\\\n                            --jobnum ${SLURM_ARRAY_JOB_ID}\\\n                            --loss ${loss}\\\n                              ${pos}\\\n                              ${more}\\\n                            --orig ${orig}_${SLURM_ARRAY_TASK_ID}.pt",
      "flux": "#!/bin/bash\n\n### --------  Flux  ----------- ###\n#FLUX --job-name=continuous\n#FLUX --nodes=1\n#FLUX --ntasks=1\n#FLUX --time=312:00:00\n\n# NOTE: This script appears to be part of a job array, based on the use of\n# SLURM_ARRAY_TASK_ID. Flux handles arrays at submission time. This script should be\n# submitted with 'flux bulksubmit'. For example, if there were 10 tasks in the array:\n# flux bulksubmit -n 10 --output=\"out/continuous_train_{id}_{task[id]}.out\" --error=\"error/continuous_train_{id}_{task[id]}.err\" ./your_script_name.sh ...args...\n# The script will then execute 10 times with FLUX_JOB_ARRAY_TASK_ID set from 0 to 9.\n# The output/error directives below are a fallback for single-job submission.\n#FLUX --output=\"out/continuous_train_{id}.out\"\n#FLUX --error=\"error/continuous_train_{id}.err\"\n\n### -------------------------- ###\n# The SLURM variables have been replaced with their Flux equivalents.\necho \"job name: $FLUX_JOB_NAME\"\necho \"FLUX_JOBID:  $FLUX_JOB_ID\"\necho \"FLUX_JOB_ARRAY_TASK_ID: $FLUX_JOB_ARRAY_TASK_ID\"\necho \"FLUX_JOB_ARRAY_ID: $FLUX_JOB_ARRAY_ID\"\n\nexport LD_LIBRARY_PATH=/usr/local/cuda-9.0/lib64:/usr/local/lib\nexport CFLAGS=-I/usr/local/cuda-9.0/include\nexport LDFLAGS=-L/usr/local/cuda-9.0/lib64\nexport PATH=$PATH:/usr/local/cuda-9.0/bin\nexport CUDA_HOME=/usr/local/cuda-9.0\nexport LIBRARY_PATH=/usr/local/cuda-9.0/lib64\n\n# NOTE: This script requires a GPU but does not explicitly request one from the scheduler.\n# It is highly recommended to add a '#FLUX --gpus=1' directive to ensure the job is\n# scheduled on a node with a GPU and that the correct device is made visible to the application.\n\nsets=$1\npretrained=$2\nbl=$3\nemdim=$4\nname=$5\ntyppe=$6\nnlayer=$7\ntbrd=$8\npre_pos=$9\nloss=${10}\npre_more=${11}\nsrc=${12}\norig=${13}\n\nif [ \"$pre_pos\" == \"True\" ]\nthen\n  pos=--pos\nfi\n\nif [ \"$pre_more\" == \"True\" ] \nthen\n  more=--more\nfi\n\n# The SLURM variables have been replaced with their Flux equivalents.\npython ${src}/continuous.py --data ${sets}/set_${FLUX_JOB_ARRAY_TASK_ID}/\\\n                            --pretrained ${pretrained}\\\n                            --save ${bl}_${FLUX_JOB_ARRAY_TASK_ID}.pt\\\n                            --emdim ${emdim}\\\n                            --log out/${name}_train_${FLUX_JOB_ARRAY_TASK_ID}\\\n                            --name $name\\\n                            --rnn_type ${typpe}\\\n                            --nlayers ${nlayer}\\\n                            --tbrd ${tbrd}\\\n                            --jobnum ${FLUX_JOB_ARRAY_ID}\\\n                            --loss ${loss}\\\n                              ${pos}\\\n                              ${more}\\\n                            --orig ${orig}_${FLUX_JOB_ARRAY_TASK_ID}.pt\n",
