      "slurm": "#!/bin/bash\n#SBATCH --gres=gpu:1       # Request GPU \"generic resources\"\n#SBATCH --cpus-per-task=6  # Cores proportional to GPUs: 6 on Cedar, 16 on Graham.\n#SBATCH --mem=20000M       # Memory proportional to GPUs: 32000 Cedar, 64000 Graham.\n#SBATCH --time=0-12:00\n#SBATCH --output=%N-%jstdmedium.out\nmodule purge\nmodule load python/3.6.3\nsource ~/env1/bin/activate\npython -m examples.lab --save_prefix=anneal-medium --dataset_for_classification=cifar_challenge --model_type=squeezenet --squeezenet_out_dim=100 --squeezenet_in_channels=3  --squeezenet_mode=next_fire --squeezenet_next_fire_groups=1 --squeezenet_pool_interval_mode=multiply  --squeezenet_base=256 --squeezenet_freq=3 --squeezenet_sr=0.25 --fire_skip_mode=simple --squeezenet_num_fires=9 --squeezenet_pool_interval=3 --squeezenet_conv1_stride=1 --squeezenet_conv1_size=3 --squeezenet_num_conv1_filters=63 --squeezenet_pooling_count_offset=0 --squeezenet_max_pool_size=2 --squeezenet_pool_interval_mode=multiply  --squeezenet_use_excitation --batch_size=64 --num_epochs=300 --optimizer=sgd --sgd_momentum=0.9  --init_lr=0.2 --lr_scheduler=epoch_anneal --epoch_anneal_numcycles=5   --epoch_anneal_save_last --squeezenet_num_layer_chunks=1 --cifar_random_erase --proxy_context_type=group_prune_context  --enable_l0reg --use_all_params     --save_every_epoch --cuda",
