      "slurm": "#!/bin/bash\n#PBS -S /bin/bash\n#PBS -l walltime=99:00:00\n#PBS -l nodes=1:ppn=8:XEON\n#PBS -m e\n#PBS -j oe\n#PBS -q benchmark\n#PBS -o pbsNAMD_mt.out\n#PBS -N testNAMD\n#\n# Change to job submission directory\n#\ncd $PBS_O_WORKDIR\n#\n# load namd via module\n#\n. $MODULESHOME/init/bash\nmodule load namd\n#\n# Set number of processors to number requested from PBS\n#\nNP=`cat $PBS_NODEFILE | wc -l`\necho \"NAMDHOME = \"$NAMDHOME\n#\n# construct namd nodes file from $PBS_NODEFILE\n#\nexport NODELIST=tmp.$$\necho \"group main\" > $NODELIST\nNODES=`cat $PBS_NODEFILE`\nfor node in $NODES ; do\n   echo \"host \"$node >> $NODELIST\ndone\n#\n# run apoa1 benchmark \n#\ncd $PBS_O_WORKDIR\n#\ncharmrun $NAMDHOME/namd2 +p$NP ++nodelist $NODELIST run_md.conf > try_3\n\\rm $NODELIST",
      "flux": "#!/bin/bash\n#FLUX --time=99:00:00\n#FLUX --nodes=1\n#FLUX --ntasks-per-node=8\n#FLUX -C XEON\n#FLUX --queue=benchmark\n#FLUX --output=pbsNAMD_mt.out\n#FLUX --job-name=testNAMD\n\n# NOTE: The PBS directive '-j oe' (join stdout/stderr) is the default behavior\n# in Flux when an error file (-e) is not specified.\n\n# NOTE: The PBS mail-on-exit directive '-m e' has been omitted, as\n# Flux does not have a direct equivalent for job status email notifications.\n\n#\n# Change to job submission directory\n#\n# The Flux equivalent of PBS_O_WORKDIR is FLUX_SUBMIT_DIR\ncd $FLUX_SUBMIT_DIR\n#\n# load namd via module\n#\n. $MODULESHOME/init/bash\nmodule load namd\n#\n# Set number of processors to number requested from Flux\n#\n# The Flux equivalent of `cat $PBS_NODEFILE | wc -l` is $FLUX_JOB_NUM_TASKS\nNP=$FLUX_JOB_NUM_TASKS\necho \"NAMDHOME = \"$NAMDHOME\n\n# NOTE: The manual creation of a nodelist for 'charmrun' is not necessary\n# when running under modern resource managers. NAMD's charmrun launcher can often\n# integrate directly with the scheduler. The original script's logic has been\n# replaced with a simpler, more standard launch command. If this fails, the\n# NAMD documentation should be consulted for proper integration with Flux.\n\n#\n# run apoa1 benchmark \n#\n# A more standard way to launch NAMD is to let charmrun discover resources\n# from the environment set by the scheduler.\ncharmrun $NAMDHOME/namd2 +p$NP run_md.conf > try_3\n",
