      "slurm": "#!/bin/bash\n#SBATCH --job-name=gptneox\n#\n#SBATCH --partition=jag-standard\n#SBATCH --gres=gpu:1\n#SBATCH --time=3:59:00\n#SBATCH --ntasks=1\n#SBATCH --cpus-per-task=2\n#SBATCH --mem-per-cpu=4G\n#SBATCH --output=/afs/cs.stanford.edu/u/biyuan/exe_log/gptneox_%j.log\nport=$1\n\nsource activate base                          # Activate my conda python environment\ncd /afs/cs.stanford.edu/u/biyuan/GPT-home-private     # Change directory\n\nnvidia-smi\n\nls -l /sys/class/net/\nnetif=`echo \"import os; print(sorted([x for x in os.listdir('/sys/class/net/') if x.startswith('en')])[0])\" | python`\necho setting network interface to $netif\nexport NCCL_SOCKET_IFNAME=$netif\nexport GLOO_SOCKET_IFNAME=$netif\nexport NCCL_DEBUG=INFO\nexport NCCL_IB_DISABLE=1\nexport NCCL_P2P_DISABLE=1\n\nworld_size=6\nmachine_size=6\nn_gpu_per_machine=$((world_size/machine_size))\n\ni=0\nwhile :\ndo\n  if [ \"$i\" -ge \"$n_gpu_per_machine\" ]; then\n      break\n  fi\n  \n  # NOTE: disable fp16 for stabler inference\n  DIST_CONF=\"--pp-mode pipe_sync_sample_mask_token_pipe --pipeline-group-size $world_size --cuda-id $i\"\n  MODEL_CONF=\"--model-type t5 --model-name /sailhome/biyuan/scratch/models/t0pp-new --num-iters 10\"\n  INFERENCE_CONF=\"--budget 2600 --batch-size 24 --input-seq-length 512 --generate-seq-length 32 --micro-batch-size 1 --num-layers 4 --max-layers 24\"\n  COOR_CONF=\"--coordinator-server-ip 10.79.12.70  --unique-port $port\"\n\n  python -u dist_inference_runner_w_slurm_coordinator.py $DIST_CONF $MODEL_CONF $INFERENCE_CONF $COOR_CONF &\n\n  ((port++))\n  ((i++))\n\ndone\n\nwait",
      "flux": "#!/bin/bash\n#FLUX --job-name=gptneox\n#FLUX --queue=jag-standard\n#FLUX --gpus=1\n#FLUX --time=3:59:00\n#FLUX --ntasks=1\n#FLUX --cpus-per-task=2\n# NOTE: Flux does not have a --mem-per-cpu option. The total memory per task\n# has been calculated (2 cpus * 4G/cpu = 8G) and specified below.\n#FLUX --mem-per-task=8G\n#FLUX --output=/afs/cs.stanford.edu/u/biyuan/exe_log/gptneox_{id}.log\nport=$1\n\nsource activate base                          # Activate my conda python environment\ncd /afs/cs.stanford.edu/u/biyuan/GPT-home-private     # Change directory\n\nnvidia-smi\n\nls -l /sys/class/net/\nnetif=`echo \"import os; print(sorted([x for x in os.listdir('/sys/class/net/') if x.startswith('en')])[0])\" | python`\necho setting network interface to $netif\nexport NCCL_SOCKET_IFNAME=$netif\nexport GLOO_SOCKET_IFNAME=$netif\nexport NCCL_DEBUG=INFO\nexport NCCL_IB_DISABLE=1\nexport NCCL_P2P_DISABLE=1\n\nworld_size=6\nmachine_size=6\n# NOTE: This script appears to be designed to run on a single machine, but the\n# launch logic seems intended to start multiple processes. The resource request\n# of a single task with one GPU conflicts with the launch logic which tries to\n# launch multiple processes based on 'n_gpu_per_machine'. The original logic\n# is preserved, but it will only launch one process given the resource request.\nn_gpu_per_machine=$((world_size/machine_size))\n\ni=0\nwhile :\ndo\n  if [ \"$i\" -ge \"$n_gpu_per_machine\" ]; then\n      break\n  fi\n  \n  # NOTE: disable fp16 for stabler inference\n  DIST_CONF=\"--pp-mode pipe_sync_sample_mask_token_pipe --pipeline-group-size $world_size --cuda-id $i\"\n  MODEL_CONF=\"--model-type t5 --model-name /sailhome/biyuan/scratch/models/t0pp-new --num-iters 10\"\n  INFERENCE_CONF=\"--budget 2600 --batch-size 24 --input-seq-length 512 --generate-seq-length 32 --micro-batch-size 1 --num-layers 4 --max-layers 24\"\n  COOR_CONF=\"--coordinator-server-ip 10.79.12.70  --unique-port $port\"\n\n  python -u dist_inference_runner_w_slurm_coordinator.py $DIST_CONF $MODEL_CONF $INFERENCE_CONF $COOR_CONF &\n\n  ((port++))\n  ((i++))\n\ndone\n\nwait\n",
