      "slurm": "#!/bin/bash\n#SBATCH -J DelSwitch\n#SBATCH -p high\n#SBATCH --exclude=node0[19-21,25]\n#SBATCH --gres=gpu:1\n#SBATCH --ntasks=1\n#SBATCH --cpus-per-task=8\n#SBATCH --mem=32G\n#SBATCH --array=0-20\n#SBATCH -o /homedtic/gjimenez/DADES/DADES/Delineator/Logs/%A-%a.out\n#SBATCH -e /homedtic/gjimenez/DADES/DADES/Delineator/Logs/%A-%a.err\n\n# Get a list of all possible models\nlist_all_models=(UNet5LevelsDiceOnly WNet5LevelsDiceOnly WNet5LevelsSelfAttentionDiceOnly WNet5LevelsSelfAttentionConvDiceOnly WNet5LevelsConvDiceOnly UNet5LevelsConvDiceOnly\nUNet6LevelsDiceOnly WNet6LevelsDiceOnly WNet6LevelsSelfAttentionDiceOnly WNet6LevelsSelfAttentionConvDiceOnly WNet6LevelsConvDiceOnly UNet6LevelsConvDiceOnly\nUNet7LevelsDiceOnly WNet7LevelsDiceOnly WNet7LevelsSelfAttentionDiceOnly WNet7LevelsSelfAttentionConvDiceOnly WNet7LevelsConvDiceOnly UNet7LevelsConvDiceOnly)\n\n# Exit if array ID larger than array length\nif [ $SLURM_ARRAY_TASK_ID -gt ${#list_all_models[@]} ];\nthen \n    exit 1\nfi\n\n# Get specific model\nmodel=${list_all_models[$SLURM_ARRAY_TASK_ID]}\n\nmodule load Python/3.6.4-foss-2017a;\nmodule load PyTorch/1.6.0-foss-2017a-Python-3.6.4-CUDA-10.1.105;\nmodule load OpenBLAS/0.2.19-foss-2017a-LAPACK-3.7.0;\nmodule load OpenMPI/2.0.2-GCC-6.3.0-2.27;\n\nexport OMP_NUM_THREADS=$SLURM_CPUS_PER_TASK;\n\nsource ~/VirtEnv/DeepLearning3/bin/activate;\ncd ~/GitHub/DelineatorSwitchAndCompose;\n\npython3 train_synth.py --config_file ./configurations/${model}.json --input_files ./pickle/ --model_name ${model}_synth_$(date '+%Y%m%d%H%M%S') --hpc 1;",
      "flux": "#!/bin/bash\n#FLUX -J DelSwitch\n#FLUX --queue=high\n\n# NOTE: SLURM's '--exclude' directive to avoid specific nodes has been omitted.\n# Flux does not have a direct equivalent in batch script directives. Similar\n# behavior can be achieved at submission time by creating a hostlist that\n# excludes the unwanted nodes.\n\n#FLUX --gpus=1\n#FLUX --ntasks=1\n#FLUX --cpus-per-task=8\n#FLUX --mem=32G\n\n# NOTE: The SLURM --array directive was omitted. Flux handles job arrays at\n# submission time. This script should be submitted using 'flux bulksubmit',\n# for example:\n# flux bulksubmit -n 21 --output=\"/homedtic/gjimenez/DADES/DADES/Delineator/Logs/{id}-{task[id]}.out\" --error=\"/homedtic/gjimenez/DADES/DADES/Delineator/Logs/{id}-{task[id]}.err\" ./your_script_name.sh\n# The script will execute 21 times with FLUX_JOB_ARRAY_TASK_ID set from 0 to 20.\n# The fallback directives below are for single-job submission.\n#FLUX -o /homedtic/gjimenez/DADES/DADES/Delineator/Logs/{id}.out\n#FLUX -e /homedtic/gjimenez/DADES/DADES/Delineator/Logs/{id}.err\n\n# Get a list of all possible models\nlist_all_models=(UNet5LevelsDiceOnly WNet5LevelsDiceOnly WNet5LevelsSelfAttentionDiceOnly WNet5LevelsSelfAttentionConvDiceOnly WNet5LevelsConvDiceOnly UNet5LevelsConvDiceOnly\nUNet6LevelsDiceOnly WNet6LevelsDiceOnly WNet6LevelsSelfAttentionDiceOnly WNet6LevelsSelfAttentionConvDiceOnly WNet6LevelsConvDiceOnly UNet6LevelsConvDiceOnly\nUNet7LevelsDiceOnly WNet7LevelsDiceOnly WNet7LevelsSelfAttentionDiceOnly WNet7LevelsSelfAttentionConvDiceOnly WNet7LevelsConvDiceOnly UNet7LevelsConvDiceOnly)\n\n# Exit if array ID larger than array length\n# The SLURM variable is replaced with the Flux equivalent.\nif [ $FLUX_JOB_ARRAY_TASK_ID -gt ${#list_all_models[@]} ];\nthen \n    exit 1\nfi\n\n# Get specific model\n# The SLURM variable is replaced with the Flux equivalent.\nmodel=${list_all_models[$FLUX_JOB_ARRAY_TASK_ID]}\n\nmodule load Python/3.6.4-foss-2017a;\nmodule load PyTorch/1.6.0-foss-2017a-Python-3.6.4-CUDA-10.1.105;\nmodule load OpenBLAS/0.2.19-foss-2017a-LAPACK-3.7.0;\nmodule load OpenMPI/2.0.2-GCC-6.3.0-2.27;\n\n# The SLURM variable is replaced with the Flux equivalent.\nexport OMP_NUM_THREADS=$FLUX_JOB_CPUS_PER_TASK;\n\nsource ~/VirtEnv/DeepLearning3/bin/activate;\ncd ~/GitHub/DelineatorSwitchAndCompose;\n\npython3 train_synth.py --config_file ./configurations/${model}.json --input_files ./pickle/ --model_name ${model}_synth_$(date '+%Y%m%d%H%M%S') --hpc 1;\n\n",
