      "slurm": "#!/bin/bash\n#SBATCH -c 1\n#SBATCH --mem=8G\n#SBATCH --gres=gpu:1\n#SBATCH --partition=compsci-gpu\n\n#########################################\n#Positional Parameters\n# $1 is the name of algorithm\n# $2 is the name of environment\n# $3 is the set of quantization bit(QAT), using 32 bit means no QAT\n# $4 is the test times(seeds number)\n# $5 is timestep for training\n########################################\n\nset -e\n\nSLURM_ARRAY_TASK_ID=204\nLearning_rate=(0.0005 0.001 0.005 0.01 0.05 0.1)\nRho=(0.01 0.02 0.05 0.1)\nlambda_hero=(0.05 0.1 0.5 1.0 5.0)\nagents=(\"a2c\" \"sac\")\nenvs=(\"Pendulum-v1\")\nseeds=(1 2 3 4)\n\nremainder=$SLURM_ARRAY_TASK_ID\nbase=$((${#Rho[@]}*${#lambda_hero[@]}*${#agents[@]}*${#envs[@]}*${#seeds[@]}))\nlr=${Learning_rate[$(($remainder/$base))]}\n\necho \"Learning rate: $lr\"\n\nremainder=$(($remainder%$base))\nbase=$((${#lambda_hero[@]}*${#agents[@]}*${#envs[@]}*${#seeds[@]}))\nrho=${Rho[$(($remainder/$base))]}\n\necho \"Rho: $rho\"\n\nremainder=$(($remainder%$base))\nbase=$((${#agents[@]}*${#envs[@]}*${#seeds[@]}))\nlambda=${lambda_hero[$(($remainder/$base))]}\n\necho \"Lambda: $lambda\"\n\nremainder=$(($remainder%$base))\nbase=$((${#envs[@]}*${#seeds[@]}))\nagent=${agents[$(($remainder/$base))]}\n\necho \"agent: $agent\"\n\nremainder=$(($remainder%$base))\nbase=$((${#seeds[@]}))\nenv=${envs[$(($remainder/$base))]}\n\necho \"env: $env\"\n#\n#remainder=$(($remainder%$base))\n#base=$seeds\n#opt=${Optimizer[$(($remainder/$base))]}\n\n#echo \"Optimizer: $opt\"\n#\ni=$(($remainder%$base))\n((i++))\necho \"Seed Number: $i\"\n\npython train.py --algo $agent --env $env --device cuda --optimize-choice HERO --quantize 32 -P --rho $rho -params learning_rate:$lr --track -n 1000000 --wandb-entity \"qorl\"\nptq_all.sh $agent $env \"logs/$agent/\"$env\"_32bit_\"$HERO\"_$i\" HERO $i $rho $lr",
      "flux": "#!/bin/bash\n#FLUX --cpus-per-task=1\n#FLUX --ntasks=1\n#FLUX --mem=8G\n#FLUX --gpus=1\n#FLUX --queue=compsci-gpu\n\n#########################################\n#Positional Parameters\n# $1 is the name of algorithm\n# $2 is the name of environment\n# $3 is the set of quantization bit(QAT), using 32 bit means no QAT\n# $4 is the test times(seeds number)\n# $5 is timestep for training\n########################################\n\n# NOTE: This script appears to be a template for a job array, but the SLURM --array\n# directive is missing and the SLURM_ARRAY_TASK_ID is hardcoded. Flux handles\n# arrays at submission time. To run this as an array job, submit with\n# 'flux bulksubmit' and replace the hardcoded value with $FLUX_JOB_ARRAY_TASK_ID.\n\nset -e\n\n# The SLURM_ARRAY_TASK_ID is hardcoded in the original script.\n# This is preserved, but for a true array job, this should be\n# replaced with $FLUX_JOB_ARRAY_TASK_ID.\nFLUX_JOB_ARRAY_TASK_ID=204\nLearning_rate=(0.0005 0.001 0.005 0.01 0.05 0.1)\nRho=(0.01 0.02 0.05 0.1)\nlambda_hero=(0.05 0.1 0.5 1.0 5.0)\nagents=(\"a2c\" \"sac\")\nenvs=(\"Pendulum-v1\")\nseeds=(1 2 3 4)\n\nremainder=$FLUX_JOB_ARRAY_TASK_ID\nbase=$((${#Rho[@]}*${#lambda_hero[@]}*${#agents[@]}*${#envs[@]}*${#seeds[@]}))\nlr=${Learning_rate[$(($remainder/$base))]}\n\necho \"Learning rate: $lr\"\n\nremainder=$(($remainder%$base))\nbase=$((${#lambda_hero[@]}*${#agents[@]}*${#envs[@]}*${#seeds[@]}))\nrho=${Rho[$(($remainder/$base))]}\n\necho \"Rho: $rho\"\n\nremainder=$(($remainder%$base))\nbase=$((${#agents[@]}*${#envs[@]}*${#seeds[@]}))\nlambda=${lambda_hero[$(($remainder/$base))]}\n\necho \"Lambda: $lambda\"\n\nremainder=$(($remainder%$base))\nbase=$((${#envs[@]}*${#seeds[@]}))\nagent=${agents[$(($remainder/$base))]}\n\necho \"agent: $agent\"\n\nremainder=$(($remainder%$base))\nbase=$((${#seeds[@]}))\nenv=${envs[$(($remainder/$base))]}\n\necho \"env: $env\"\n#\n#remainder=$(($remainder%$base))\n#base=$seeds\n#opt=${Optimizer[$(($remainder/$base))]}\n\n#echo \"Optimizer: $opt\"\n#\ni=$(($remainder%$base))\n((i++))\necho \"Seed Number: $i\"\n\npython train.py --algo $agent --env $env --device cuda --optimize-choice HERO --quantize 32 -P --rho $rho -params learning_rate:$lr --track -n 1000000 --wandb-entity \"qorl\"\nptq_all.sh $agent $env \"logs/$agent/\"$env\"_32bit_\"$HERO\"_$i\" HERO $i $rho $lr\n",
