      "slurm": "#!/bin/bash\n\n# Copyright (C) 2020 Tobias Jakobi\n#\n# This program is free software: you can redistribute it and/or modify\n# it under the terms of the GNU General Public License as published by\n# the Free Software Foundation, either self.version 3 of the License, or\n# (at your option) any later self.version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program.  If not, see <http://www.gnu.org/licenses/>.\n\n# @Author: Tobias Jakobi <tjakobi>\n# @Email:  tobias.jakobi@med.uni-heidelberg.de\n# @Project: University Hospital Heidelberg, Section of Bioinformatics and Systems Cardiology\n\n#SBATCH -n 1\n#SBATCH -N 1\n#SBATCH -c 10\n#SBATCH -p gpu\n#SBATCH --mem=70G\n#SBATCH -J \"Taiyaki\"\n#SBATCH --mail-type=END,FAIL,TIME_LIMIT_80\n#SBATCH --mail-user=tobias.jakobi@med.uni-heidelberg.de\n#SBATCH --gres=gpu:tesla:1\n\nmodule unload cuda\n\n\n################################################################################################\necho \"==== Start of GPU information ====\"\n\nCUDA_DEVICE=$(echo \"$CUDA_VISIBLE_DEVICES,\" | cut -d',' -f $((SLURM_LOCALID + 1)) );\nT_REGEX='^[0-9]$';\nif ! [[ \"$CUDA_DEVICE\" =~ $T_REGEX ]]; then\n        echo \"error no reserved gpu provided\"\n        exit 1;\nfi\n\n# Print debug information\n\necho -e \"SLURM job:\\t$SLURM_JOBID\"\necho -e \"SLURM process:\\t$SLURM_PROCID\"\necho -e \"SLURM GPU ID:\\t$SLURM_LOCALID\"\necho -e \"CUDA_DEVICE ID:\\t$CUDA_DEVICE\"\necho -e \"CUDA_VISIBLE_DEVICES:\\t$CUDA_VISIBLE_DEVICES\"\necho \"Device list:\"\necho \"$(nvidia-smi --query-gpu=name,gpu_uuid --format=csv -i $CUDA_VISIBLE_DEVICES | tail -n +2)\"\necho \"==== End of GPU information ====\"\necho \"\"\n#################################################################################################\n\n\nmodule load taiyaki\n\n\n# check if we have 4 arguments\nif [ ! $# == 4 ]; then\n  echo \"Usage: $0 [Read directory (FAST5)] [target dir e.g. /tmp/] [pretrained model] [FASTA read training set]\"\n  exit\nfi\n\nreads=$1\nout=$2\npretrained_model=$3\nfasta_file=$4\n\n#CUDA_VISIBLE_DEVICES=0\n\n# create the target directory\nmkdir $out -pv\n\n#echo \"======== generate per read params\"\n\ntime generate_per_read_params.py --jobs 30 $reads > $out/modbase.tsv\n\n#echo \"======== prepare mapped reads\"\n\ntime prepare_mapped_reads.py --jobs 30 --overwrite --alphabet ACGT --mod Y A 6mA $reads $out/modbase.tsv $out/modbase.hdf5 $pretrained_model $fasta_file\n\necho \"======== training1\"\n\ntime train_flipflop.py --full_filter_status --overwrite --device 0 --chunk_len_min 2000 --chunk_len_max 4000 --size 256 --stride 10 --winlen 31 --mod_factor 0.01 --outdir $out/training /biosw/taiyaki/5.0.1/models/mGru_cat_mod_flipflop.py $out/modbase.hdf5\n\necho \"======== training2\"\n\ntime train_flipflop.py --full_filter_status --overwrite --device 0 --chunk_len_min 2000 --chunk_len_max 4000 --size 256 --stride 10 --winlen 31 --mod_factor 0.1 --outdir $out/training2 $out/training/model_final.checkpoint $out/modbase.hdf5\n\n#echo \"======== basecall\"\n#time basecall.py --alphabet ACGT --device 0 --modified_base_output $out/basecalls.hdf5 $reads $out/training2/model_final.checkpoint  > $out/basecalls.fa",
      "flux": "#!/bin/bash\n\n# Copyright (C) 2020 Tobias Jakobi\n#\n# This program is free software: you can redistribute it and/or modify\n# it under the terms of the GNU General Public License as published by\n# the Free Software Foundation, either self.version 3 of the License, or\n# (at your option) any later self.version.\n#\n# This program is distributed in the hope that it will be useful,\n# but WITHOUT ANY WARRANTY; without even the implied warranty of\n# MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n# GNU General Public License for more details.\n#\n# You should have received a copy of the GNU General Public License\n# along with this program.  If not, see <http://www.gnu.org/licenses/>.\n\n# @Author: Tobias Jakobi <tjakobi>\n# @Email:  tobias.jakobi@med.uni-heidelberg.de\n# @Project: University Hospital Heidelberg, Section of Bioinformatics and Systems Cardiology\n\n#FLUX --ntasks=1\n#FLUX --nodes=1\n#FLUX --cpus-per-task=10\n#FLUX --queue=gpu\n#FLUX --mem=70G\n#FLUX --job-name=\"Taiyaki\"\n# To request a specific GPU type, Flux uses a combination of gpu count and constraints.\n#FLUX --gpus=1\n#FLUX -C tesla\n\n# NOTE: The --mail-user and --mail-type directives have been omitted as Flux\n# does not have a direct equivalent for job status email notifications.\n\nmodule unload cuda\n\n\n################################################################################################\necho \"==== Start of GPU information ====\"\n\n# NOTE: The logic for manually selecting a GPU from CUDA_VISIBLE_DEVICES has been removed.\n# Flux allocates a specific GPU to a task and sets CUDA_VISIBLE_DEVICES to ensure\n# the task only sees its assigned GPU, typically as device 0. The original logic\n# was complex and unnecessary in a standard Flux environment.\n\n# Print debug information\n# The SLURM variables have been replaced with their Flux equivalents.\necho -e \"FLUX job:\\t$FLUX_JOB_ID\"\necho -e \"FLUX process:\\t$FLUX_TASK_RANK\"\necho -e \"FLUX task local ID:\\t$FLUX_TASK_LOCAL_ID\"\necho -e \"CUDA_VISIBLE_DEVICES:\\t$CUDA_VISIBLE_DEVICES\"\necho \"Device list:\"\necho \"$(nvidia-smi --query-gpu=name,gpu_uuid --format=csv -i $CUDA_VISIBLE_DEVICES | tail -n +2)\"\necho \"==== End of GPU information ====\"\necho \"\"\n#################################################################################################\n\n\nmodule load taiyaki\n\n\n# check if we have 4 arguments\nif [ ! $# == 4 ]; then\n  echo \"Usage: $0 [Read directory (FAST5)] [target dir e.g. /tmp/] [pretrained model] [FASTA read training set]\"\n  exit\nfi\n\nreads=$1\nout=$2\npretrained_model=$3\nfasta_file=$4\n\n# create the target directory\nmkdir $out -pv\n\n#echo \"======== generate per read params\"\n\ntime generate_per_read_params.py --jobs 30 $reads > $out/modbase.tsv\n\n#echo \"======== prepare mapped reads\"\n\ntime prepare_mapped_reads.py --jobs 30 --overwrite --alphabet ACGT --mod Y A 6mA $reads $out/modbase.tsv $out/modbase.hdf5 $pretrained_model $fasta_file\n\necho \"======== training1\"\n\ntime train_flipflop.py --full_filter_status --overwrite --device 0 --chunk_len_min 2000 --chunk_len_max 4000 --size 256 --stride 10 --winlen 31 --mod_factor 0.01 --outdir $out/training /biosw/taiyaki/5.0.1/models/mGru_cat_mod_flipflop.py $out/modbase.hdf5\n\necho \"======== training2\"\n\ntime train_flipflop.py --full_filter_status --overwrite --device 0 --chunk_len_min 2000 --chunk_len_max 4000 --size 256 --stride 10 --winlen 31 --mod_factor 0.1 --outdir $out/training2 $out/training/model_final.checkpoint $out/modbase.hdf5\n\n#echo \"======== basecall\"\n#time basecall.py --alphabet ACGT --device 0 --modified_base_output $out/basecalls.hdf5 $reads $out/training2/model_final.checkpoint  > $out/basecalls.fa\n\n",
