      "slurm": "#!/bin/bash\n# Job Name and Files (also --job-name)\n#SBATCH -J LIKWID\n#Output and error (also --output, --error):\n#SBATCH -o data-512.out\n#SBATCH -e data-512.e\n#Initial working directory (also --chdir):\n#SBATCH -D ./\n#Notification and type\n#SBATCH --mail-type=END\n#SBATCH --mail-user=munch@lnm.mw.tum.de\n# Wall clock limit:\n#SBATCH --time=1:00:00\n#SBATCH --no-requeue\n#Setup of execution environment\n#SBATCH --export=NONE\n#SBATCH --get-user-env\n#SBATCH --account=pr83te\n#\n## #SBATCH --switches=4@24:00:00\n#SBATCH --partition=general\n#Number of nodes and MPI tasks per node:\n#SBATCH --nodes=512\n#SBATCH --ntasks-per-node=48\n#SBATCH --cpus-per-task=1\n\n#module list\n\n#source ~/.bashrc\n# lscpu\n\n#module unload mkl mpi.intel intel\n#module load intel/19.0 mkl/2019\n#module load gcc/9\n#module unload mpi.intel\n#module load mpi.intel/2019_gcc\n#module load cmake\n#module load slurm_setup\n\nmodule unload intel-mpi/2019-intel\nmodule unload intel/19.0.5\nmodule load gcc/9\nmodule load intel-mpi/2019-gcc\n\n\npwd\n\narray=($(ls input_*.json));\nmpirun -np 24576 ../multigrid_throughput \"${array[@]}\"",
      "flux": "#!/bin/bash\n# Job Name and Files (also --job-name)\n#FLUX -J LIKWID\n#Output and error (also --output, --error):\n#FLUX -o data-512.out\n#FLUX -e data-512.e\n#Initial working directory (also --chdir):\n#FLUX --chdir=./\n#Notification and type\n# NOTE: The --mail-user and --mail-type directives have been omitted as Flux\n# does not have a direct equivalent for job status email notifications.\n# Wall clock limit:\n#FLUX --time=1:00:00\n\n# NOTE: The SLURM '--no-requeue' option is not directly translatable to Flux.\n# Job requeue behavior in Flux is typically configured at the system level.\n\n#Setup of execution environment\n# NOTE: SLURM's '--export=NONE' prevents the job from inheriting the user's\n# environment. Flux does not have a direct equivalent for this behavior.\n\n# NOTE: The SLURM '--get-user-env' directive is generally the default behavior for\n# schedulers and does not require an explicit option in Flux.\n\n#FLUX --account=pr83te\n#FLUX --queue=general\n#Number of nodes and MPI tasks per node:\n#FLUX --nodes=512\n#FLUX --ntasks-per-node=48\n#FLUX --cpus-per-task=1\n\n#module list\n\n#source ~/.bashrc\n# lscpu\n\n#module unload mkl mpi.intel intel\n#module load intel/19.0 mkl/2019\n#module load gcc/9\n#module unload mpi.intel\n#module load mpi.intel/2019_gcc\n#module load cmake\n#module load slurm_setup\n\nmodule unload intel-mpi/2019-intel\nmodule unload intel/19.0.5\nmodule load gcc/9\nmodule load intel-mpi/2019-gcc\n\n\npwd\n\narray=($(ls input_*.json));\n# 'mpirun' is replaced by Flux's native launcher, 'flux run'.\n# The number of tasks (24576) matches the total requested for the job\n# (512 nodes * 48 tasks/node), so Flux will use the full allocation.\nflux run -n 24576 ../multigrid_throughput \"${array[@]}\"\n\n\n",
