              "jobspec": "#!/bin/bash\n#FLUX --queue=cpu\n#FLUX --job-name=Preprocess-Megatron-BERT\n#FLUX --mem=512G\n#FLUX --nodes=1\n#FLUX --cpus-per-task=128\n#FLUX --ntasks=1\n#FLUX --time=12:00:00\n#FLUX --output=logs/sbatch.log\n\n# REMEMBER TO CHANGE: --mem, --gres, --gpus-per-node, --time\necho \"Inside sbatch_run.sh script...\"\n\n# module purge\n# conda deactivate\n\naddr=$(/bin/hostname -s)\nexport MASTER_ADDR=$addr\nexport MASTER_PORT=56781\n# export NPROC_PER_NODE=$SLURM_GPUS_PER_NODE\n\n# debugging flags (optional)\nexport NCCL_DEBUG=INFO\nexport PYTHONFAULTHANDLER=1\n\nDATETIME=$(date +'date_%y-%m-%d_time_%H-%M-%S')\n\nPROJECT=/ceph/hpc/home/eujoeyo/group_space/joey/workspace/Megatron-LM\nTARGET_DIR=\"/workspace/Megatron-LM\"\nCONTAINER_PATH=\"/ceph/hpc/home/eujoeyo/group_space/containers/megatron-deepspeed.sif\"\nLOGGING=$PROJECT/logs\n\n# The SLURM variables have been replaced with their Flux equivalents.\necho \"FLUX_JOB_NCPUS\" $FLUX_JOB_NCPUS\n# echo \"NPROC_PER_NODE\" $NPROC_PER_NODE\necho \"FLUX_JOB_NAME\" $FLUX_JOB_NAME\necho \"FLUX_JOB_ID\" $FLUX_JOB_ID\necho \"FLUX_JOB_NODELIST\" $FLUX_JOB_NODELIST\necho \"FLUX_JOB_NNODES\" $FLUX_JOB_NNODES\necho \"FLUX_TASK_LOCAL_ID\" $FLUX_TASK_LOCAL_ID\necho \"FLUX_NODEID\" $FLUX_NODEID\necho \"FLUX_TASK_RANK\" $FLUX_TASK_RANK\n\n# 'srun' is replaced by 'flux run'. Since this is a single-task, single-node job,\n# the launch command is simplified.\ncmd=\"flux run --output=$LOGGING/srun_$DATETIME.log \\\n  singularity exec --nv --pwd /workspace/Megatron-LM --bind $PROJECT:$TARGET_DIR $CONTAINER_PATH ./preprocess.sh\"\n\n# cmd=\"singularity exec --nv --pwd /workspace/DeepSpeedBert --bind $PROJECT:$TARGET_DIR $CONTAINER_PATH ./start_training.sh\"\n\necho \"Executing:\"\necho $cmd\n\n$cmd\n\nset +x\n\nexit 0\n",
