              "jobspec": "#!/bin/bash\n\n##########\n# Flux parameters\n##########\n\n# NOTE: This script is a template. Placeholders like '%qos' must be filled in\n# before submission.\n\n# Set QoS\n#FLUX --qos=%qos\n\n# Set partition/queue\n#FLUX --queue=%partition\n\n# Set the number of nodes\n#FLUX --nodes=1\n\n# Set max wallclock time\n#FLUX --time=2d\n\n# Set name of job\n#FLUX --job-name=pytorch_gan_zoo_cifar10\n\n# Set number of GPUs\n#FLUX --gpus=1\n\n##########\n# Modules\n##########\n\nmodule purge\nmodule load %modules\n\n##########\n# Job parameters\n##########\n\n# Unique Job ID. The logic is adapted for Flux array job variables.\nif [ \"$FLUX_JOB_ARRAY_ID\" ]; then\n    job_id=\"${FLUX_JOB_ARRAY_ID}_${FLUX_JOB_ARRAY_TASK_ID}\"\nelse\n    job_id=\"$FLUX_JOB_ID\"\nfi\n\n# Path to scratch directory on host\nscratch_host=\"%scratch_host\"\nscratch=\"$scratch_host/$job_id\"\n# Files and directories to copy to scratch before the job\ninputs=\"cifar10 config_cifar10.json\"\n# File and directories to copy from scratch after the job\noutputs=\"output_networks/cifar10_$job_id\"\n# Singularity container\ncontainer=\"pytorch_GAN_zoo.sif\"\n# Singularity 'exec' command\ncontainer_command=\"train.py PGAN -c config_cifar10.json --restart --no_vis -n cifar10_$job_id\"\n# Command to execute\nrun_command=\"singularity exec \\\n  --nv \\\n  --bind $scratch:/scratch_mount \\\n  --pwd /scratch_mount \\\n  $container \\\n  $container_command\"\n\n##########\n# Set up scratch\n##########\n\n# Copy inputs to scratch\nmkdir -p \"$scratch\"\nfor item in $inputs; do\n    echo \"Copying $item to scratch\"\n    cp -r \"$item\" \"$scratch\"\ndone\n\n##########\n# Monitor and run job\n##########\n\n# Monitor GPU usage\nnvidia-smi dmon -o TD -s puct -d 1 > \"dmon_$job_id\".txt &\ngpu_watch_pid=$!\n\n# run the application\nstart_time=$(date -Is --utc)\n$run_command\nend_time=$(date -Is --utc)\n\n# Stop GPU monitoring\nkill $gpu_watch_pid\n\n# Print summary\necho \"executed: $run_command\"\necho \"started: $start_time\"\necho \"finished: $end_time\"\n\n##########\n# Copy outputs\n##########\n\n# Copy output from scratch\nfor item in $outputs; do\n    echo \"Copying $item from scratch\"\n    cp -r \"$scratch/$item\" ./\ndone\n\n# Clean up scratch directory\nrm -rf \"$scratch\"\n"
