              "jobspec": "#!/usr/bin/env bash\n\n#FLUX --job-name=hypre@2.23.0\n#FLUX --account=sdsc\n#FLUX --queue=hotel\n#FLUX --nodes=1\n#FLUX --ntasks-per-node=1\n#FLUX --cpus-per-task=16\n#FLUX --mem=32G\n#FLUX --time=00:30:00\n# NOTE: Flux does not have a token for the nodename in the output file path.\n# The SLURM %N token has been omitted.\n#FLUX --output={name}.o{id}\n\ndeclare -xr LOCAL_TIME=\"$(date +'%Y%m%dT%H%M%S%z')\"\ndeclare -xir UNIX_TIME=\"$(date +'%s')\"\n\ndeclare -xr SYSTEM_NAME='expanse'\n\ndeclare -xr SPACK_VERSION='0.17.3'\ndeclare -xr SPACK_INSTANCE_NAME='cpu'\ndeclare -xr SPACK_INSTANCE_DIR=\"$(HOME)/cm/shared/apps/spack/${SPACK_VERSION}/${SPACK_INSTANCE_NAME}\"\n\n# NOTE: The logic to find the job script via `scontrol` is SLURM-specific.\n# A more portable BASH method is used to find the running script's path.\ndeclare -xr FLUX_JOB_SCRIPT=\"$(readlink -f \"${BASH_SOURCE[0]}\")\"\ndeclare -xr FLUX_JOB_MD5SUM=\"$(md5sum \"${FLUX_JOB_SCRIPT}\")\"\n\ndeclare -xr SCHEDULER_MODULE='slurm'\n\n# The SLURM variables are replaced with their Flux equivalents.\necho \"${UNIX_TIME} ${FLUX_JOB_ID} ${FLUX_JOB_MD5SUM} ${FLUX_JOB_DEPENDENCY}\" \necho \"\"\n\ncat \"${FLUX_JOB_SCRIPT}\"\n\nmodule purge\n# NOTE: The 'slurm' module may need to be removed or replaced when running in a pure Flux environment.\nmodule load \"${SCHEDULER_MODULE}\"\nmodule list\n. \"${SPACK_INSTANCE_DIR}/share/spack/setup-env.sh\"\n\ndeclare -xr SPACK_PACKAGE='hypre@2.23.0'\ndeclare -xr SPACK_COMPILER='gcc@10.2.0'\ndeclare -xr SPACK_VARIANTS='~complex ~cuda ~debug +fortran ~int64 ~internal-superlu ~mixedint +mpi ~openmp +shared +superlu-dist ~unified-memory'\ndeclare -xr SPACK_DEPENDENCIES=\"^openblas@0.3.17/$(spack find --format '{hash:7}' openblas@0.3.17 % ${SPACK_COMPILER} ~ilp64 threads=none) ^superlu-dist@7.1.1/$(spack find --format '{hash:7}' superlu-dist@7.1.1 % ${SPACK_COMPILER} ^openmpi@3.1.6)\"\ndeclare -xr SPACK_SPEC=\"${SPACK_PACKAGE} % ${SPACK_COMPILER} ${SPACK_VARIANTS} ${SPACK_DEPENDENCIES}\"\n\nprintenv\n\nspack config get compilers\nspack config get config  \nspack config get mirrors\nspack config get modules\nspack config get packages\nspack config get repos\nspack config get upstreams\n\nspack spec --long --namespaces --types \"${SPACK_SPEC}\"\nif [[ \"${?}\" -ne 0 ]]; then\n  echo 'ERROR: spack concretization failed.'\n  exit 1\nfi\n\n# The SLURM_CPUS_PER_TASK variable is replaced with the Flux equivalent.\ntime -p spack install --jobs \"${FLUX_JOB_CPUS_PER_TASK}\" --fail-fast --yes-to-all \"${SPACK_SPEC}\"\nif [[ \"${?}\" -ne 0 ]]; then\n  echo 'ERROR: spack install failed.'\n  exit 1\nfi\n\nspack module lmod refresh --delete-tree -y\n\n# 'sbatch' is replaced by 'flux submit' for job chaining.\nflux submit --dependency=\"afterok:${FLUX_JOB_ID}\" 'valgrind@3.17.0.sh'\n\nsleep 60\n",
