      "slurm": "#!/bin/bash\n#SBATCH --ntasks=4               # total number of tasks across all nodes\n#SBATCH --cpus-per-task=1        # cpu-cores per task (>1 if multi-threaded tasks)\n#SBATCH --mem-per-cpu=4G       # memory per cpu-core (4G is default)\n#SBATCH --time=24:00:00          # total run time limit (HH:MM:SS)\n#SBATCH --job-name=\"rerunREPLACE\" \n#SBATCH --hint=multithread\n#SBATCH --gres=gpu:1             # number of gpus per node\n\nexport OMP_NUM_THREADS=$SLURM_CPUS_PER_TASK\nexport PLUMED_NUM_THREADS=$SLURM_CPUS_PER_TASK\n\npwd; hostname; date\n\nmodule purge\nmodule load rh/devtoolset/4\nmodule load cudatoolkit/10.0\nmodule load cudnn/cuda-10.0/7.6.3\nmodule load openmpi/gcc/3.1.3/64\n\nexport PLUMED_MAXBACKUP=500\n\n############################################################################\n# Variables definition\n############################################################################\nLAMMPS_EXE=/home/ppiaggi/Programs/Software-deepmd-kit-1.0/lammps-git2/src/lmp_mpi\nsource /home/ppiaggi/Programs/Software-deepmd-kit-1.0/tensorflow-venv/bin/activate\ncycles=1\npartitions=1\n############################################################################\n\n############################################################################\n# Run\n############################################################################\nif [ -e runno ] ; then\n   #########################################################################\n   # Restart runs\n   #########################################################################\n   nn=`tail -n 1 runno | awk '{print $1}'`\n   mpirun -np $SLURM_NTASKS $LAMMPS_EXE -sf omp -partition ${partitions}x4 -in Restart.lmp\n   #########################################################################\nelse\n   #########################################################################\n   # First run\n   #########################################################################\n   nn=1\n   # Number of partitions\n   mpirun -np $SLURM_NTASKS $LAMMPS_EXE -sf omp -partition ${partitions}x4 -in start.lmp\n   #########################################################################\nfi\n############################################################################\n\n\n############################################################################\n# Prepare next run\n############################################################################\n# Back up\n############################################################################\nfor j in $(seq 0 3)\ndo\n        cp restart2.lmp.${j} restart2.lmp.${j}.${nn}\n        cp restart.lmp.${j} restart.lmp.${j}.${nn}\n        cp data.final.${j} data.final.${j}.${nn}\ndone\n\n############################################################################\n# Check number of cycles\n############################################################################\nmm=$((nn+1))\necho ${mm} > runno\n#cheking number of cycles\nif [ ${nn} -ge ${cycles} ]; then\n  exit\nfi\n############################################################################\n\n############################################################################\n# Resubmitting again\n############################################################################\nsbatch < job.sh\n############################################################################\n\ndate",
      "flux": "#!/bin/bash\n#FLUX --ntasks=4               # total number of tasks across all nodes\n#FLUX --cpus-per-task=1        # cpu-cores per task (>1 if multi-threaded tasks)\n#FLUX --mem-per-cpu=4G       # memory per cpu-core (4G is default)\n#FLUX --time=24:00:00          # total run time limit (HH:MM:SS)\n#FLUX --job-name=\"rerunREPLACE\" \n# NOTE: The SLURM hint '--hint=multithread' has been omitted as there is no\n# direct Flux equivalent. Flux's default binding may utilize SMT/hyper-threading\n# if available.\n#FLUX --gpus=1             # number of gpus per node\n\n# The SLURM variables are replaced with their Flux equivalents.\nexport OMP_NUM_THREADS=$FLUX_JOB_CPUS_PER_TASK\nexport PLUMED_NUM_THREADS=$FLUX_JOB_CPUS_PER_TASK\n\npwd; hostname; date\n\nmodule purge\nmodule load rh/devtoolset/4\nmodule load cudatoolkit/10.0\nmodule load cudnn/cuda-10.0/7.6.3\nmodule load openmpi/gcc/3.1.3/64\n\nexport PLUMED_MAXBACKUP=500\n\n############################################################################\n# Variables definition\n############################################################################\nLAMMPS_EXE=/home/ppiaggi/Programs/Software-deepmd-kit-1.0/lammps-git2/src/lmp_mpi\nsource /home/ppiaggi/Programs/Software-deepmd-kit-1.0/tensorflow-venv/bin/activate\ncycles=1\npartitions=1\n############################################################################\n\n############################################################################\n# Run\n############################################################################\nif [ -e runno ] ; then\n   #########################################################################\n   # Restart runs\n   #########################################################################\n   nn=`tail -n 1 runno | awk '{print $1}'`\n   # 'mpirun' is replaced with 'flux run'. The SLURM_NTASKS variable is replaced\n   # with the Flux equivalent.\n   flux run -n $FLUX_JOB_NUM_TASKS $LAMMPS_EXE -sf omp -partition ${partitions}x4 -in Restart.lmp\n   #########################################################################\nelse\n   #########################################################################\n   # First run\n   #########################################################################\n   nn=1\n   # Number of partitions\n   flux run -n $FLUX_JOB_NUM_TASKS $LAMMPS_EXE -sf omp -partition ${partitions}x4 -in start.lmp\n   #########################################################################\nfi\n############################################################################\n\n\n############################################################################\n# Prepare next run\n############################################################################\n# Back up\n############################################################################\nfor j in $(seq 0 3)\ndo\n        cp restart2.lmp.${j} restart2.lmp.${j}.${nn}\n        cp restart.lmp.${j} restart.lmp.${j}.${nn}\n        cp data.final.${j} data.final.${j}.${nn}\ndone\n\n############################################################################\n# Check number of cycles\n############################################################################\nmm=$((nn+1))\necho ${mm} > runno\n#cheking number of cycles\nif [ ${nn} -ge ${cycles} ]; then\n  exit\nfi\n############################################################################\n\n############################################################################\n# Resubmitting again\n############################################################################\n# 'sbatch' is replaced with 'flux submit' for job chaining.\nflux submit < job.sh\n############################################################################\n\ndate\n",
